arguments.command:
cat > /tmp/friends-work/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  Username*) echo x-access-token ;;
  Password*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/friends-work/askpass.sh
GIT_ASKPASS=/tmp/friends-work/askpass.sh git -C /tmp/friends-work/chandler push origin HEAD:refs/heads/friend/chandler 2>&1 | tail -3
